BEGIN TRANSACTION;
CREATE TABLE daymark_entities (workspace TEXT NOT NULL,id TEXT NOT NULL,kind TEXT NOT NULL,version INTEGER NOT NULL,data TEXT NOT NULL,status TEXT,archived INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(workspace,id));
CREATE TABLE daymark_event_cursors (workspace TEXT NOT NULL,seq INTEGER NOT NULL,event_seq INTEGER NOT NULL UNIQUE,PRIMARY KEY(workspace,seq));
CREATE TABLE daymark_events (seq INTEGER PRIMARY KEY AUTOINCREMENT,workspace TEXT NOT NULL,operation_id TEXT,entity_id TEXT,action TEXT NOT NULL,before_data TEXT,after_data TEXT,created_at TEXT NOT NULL,actor TEXT);
CREATE TABLE daymark_operations (workspace TEXT NOT NULL,operation_id TEXT NOT NULL,payload_hash TEXT NOT NULL,result TEXT NOT NULL,PRIMARY KEY(workspace,operation_id));
CREATE TABLE daymark_refs (workspace TEXT NOT NULL,source_id TEXT NOT NULL,field TEXT NOT NULL,target_id TEXT NOT NULL,PRIMARY KEY(workspace,source_id,field,target_id)) WITHOUT ROWID;
CREATE TABLE daymark_scheduler (key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE daymark_sources (workspace TEXT NOT NULL,system TEXT NOT NULL,kind TEXT NOT NULL,ref_id TEXT NOT NULL,entity_id TEXT NOT NULL,PRIMARY KEY(workspace,system,kind,ref_id)) WITHOUT ROWID;
CREATE INDEX daymark_refs_target ON daymark_refs(workspace,target_id);
CREATE INDEX daymark_sources_entity ON daymark_sources(workspace,entity_id);
CREATE INDEX daymark_events_entity ON daymark_events(workspace,entity_id,seq);
CREATE INDEX daymark_entities_kind ON daymark_entities(kind,workspace,status);
DELETE FROM "sqlite_sequence";
COMMIT;
